#[test]
fn dart_adapter_no_fca_source_no_error() {
    let dart = DartAdapter;
    assert!(dart.as_fca_source().is_none());
    // Dispatch falls back to cross-language:
    let registry = default_registry();
    let sym = SymbolRow { kind: "function".into(), ... };
    let attrs = crate::fca::extract_attrs_for_symbol(&sym, "lib/foo.dart", "dart", &registry).unwrap();
    assert!(attrs.attributes.contains(&"kind:function".to_string()));
    assert!(!attrs.attributes.contains(&"returns_result".to_string())); // no lang-specific
}
